#%% Testing algorithms
for histval in histvals:
    
    smoothed_histvals, min_indices, max_indices, black_point_guess = find_black_point(histval)

    plt.figure(dpi=300)
    plt.plot(histval)
    plt.plot(smoothed_histvals)
    for min_index in min_indices:
        if smoothed_histvals[min_index] < 1000:
            plt.axvline(x=min_index, color='red', linestyle='--')
        else:
            plt.axvline(x=min_index, color='red')            
    for max_index in max_indices:
        plt.axvline(x=max_index, color='green')
    plt.axvline(x=black_point_guess, color='black')
    
    plt.show()
    
